                config, events, True, max_record_work
            )
        else:
            result, observer = _run_reload(
                config, events, True, max_record_work
            )
        doc = _build_log_doc(config, events, observer["items"])
        payload = _log_bytes(doc)
        # 字节上界（含末尾 LF）在写入前判定；等于上限合法
        if len(payload) > max_log_bytes:
            _fail("log_limit")
            return 5
        # 输出上界在 log_limit 之后、原子写 LOG 之前判定；超限时绝不触碰 LOG
        output = _result_bytes(result)
        if len(output) > max_output_bytes:
            _fail("output_limit")
            return 5
        _atomic_write(log_path, payload)  # 成功后才原子写 LOG
    except InvalidInput:
        _fail("invalid_input")
        return 4
    except (
        ReloadWorkLimit,
        StpWorkLimit,
        LoopWorkLimit,
        ForwardWorkLimit,
        ForwardStpWorkLimit,
        LinkForwardWorkLimit,
        LinkWorkLimit,
        SecurityWorkLimit,
        QosWorkLimit,
        AclWorkLimit,
        MirrorWorkLimit,
        LagWorkLimit,
        StormWorkLimit,
    ):
        _fail("record_work_limit")
        return 5
    except OSError:
        _fail("file_not_found")
        return 3
    sys.stdout.buffer.write(output)
    return 0


def _cmd_replay(
    log_path,
    max_events,
    max_log_bytes,
    max_output_bytes,
    max_replay_work,
    expected_sha256=None,
):
    try:
        with open(log_path, "rb") as handle:
            log_raw = _read_limited(handle, max_log_bytes)
    except OSError:
        _fail("file_not_found")
        return 3
    # 字节上界先判定（分块读取、超限即停，含末尾 LF）
    if log_raw is None:
        _fail("log_limit")
        return 5
    try:
        log = parse_json(log_raw)  # 全量校验先于重放
        _validate_log_shape(log)
        if hashlib.sha256(_log_prefix_bytes(log)).hexdigest() != log["sha256"]:
            raise InvalidInput("bad log sha256")
        # 外部承诺先于事件数与一切语义重放：EXPECTED 须是调用方从成功
